head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 inputCalendar 의 calendarValueType 부분을 확인한다.
    //1. In the Source tab, check the calendarValueType part of inputCalendar.
    //Verify step 1. calendarValueType="yearMonthDateTimeSec" 
    //1. calendarValueType = "yearMonthDateTimeSec"
    //Test step 2. skipConfirmOnly 부분을 확인한다.
    //2. Check the skipConfirmOnly part.
    //Verify step 2. skipConfirmOnly="true"
    //2. skipConfirmOnly = "true"
    //Test step 3. 브라우저에서 inputCalendar 의 날짜를 선택한다. (코멘트 참고)
    //3. In the browser, select the date of inputCalendar. (See comment)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_img').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_calendar_cell_3_2').click()");
    //Verify step 3. 적용버튼이 있지만, 날짜만 선택해도 데이터가 적용된다.
    //3. There is an Apply button, but the data will be applied even if only the date is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'wq_uuid_3_calendar')).is(':visible')", "false");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData([1, 20160831, 2, 11, 20160901, 22]);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 26-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
